  dbr:Hurricane_at_Pilgrim_Hill dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }

  OPTIONAL { ?director dbo:deathPlace ?deathPlaceOnt . }
  OPTIONAL { ?deathPlaceOnt rdfs:label ?deathPlaceOntLabel FILTER(lang(?deathPlaceOntLabel) = 'en') }

  OPTIONAL { ?director dbp:deathPlace ?deathPlaceLiteral . }
  OPTIONAL {
    ?candidate rdfs:label ?candidateLabel FILTER(lang(?candidateLabel) = 'en') .
    FILTER(bound(?deathPlaceLiteral) && CONTAINS(LCASE(STR(?deathPlaceLiteral)), LCASE(STR(?candidateLabel))))
  }

  BIND(COALESCE(?deathPlaceOnt, ?candidate) AS ?deathPlace)
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = 'en') }
}

