  dbr:Hurricane_at_Pilgrim_Hill dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }

  ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = 'en') .
  FILTER(CONTAINS(LCASE(STR(?placeLabel)), "newport beach"))
}

