  dbr:Hurricane_at_Pilgrim_Hill dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }

  ?place rdfs:label "Newport Beach, California"@en .
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = 'en') }
}

SELECT DISTINCT ?director ?directorLabel ?place ?placeLabel WHERE {
  dbr:Hurricane_at_Pilgrim_Hill dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }

  ?place rdfs:label "Newport Beach, California"@en .
  FILTER(!STRSTARTS(STR(?place), "http://dbpedia.org/resource/Category:"))
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = 'en') }
}

