PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?director ?directorLabel ?place ?placeLabel WHERE {
  dbr:Hurricane_at_Pilgrim_Hill dbo:director ?director .
  OPTIONAL {
    ?director rdfs:label ?directorLabel
    FILTER(lang(?directorLabel) = 'en')
  }
  ?place rdfs:label "Newport Beach, California" @en .
  FILTER(! STRSTARTS(STR(?place) , "http://dbpedia.org/resource/Category:"))
  OPTIONAL {
    ?place rdfs:label ?placeLabel
    FILTER(lang(?placeLabel) = 'en')
  }
}

